/**
Decode the JSON Web Token (JWT) and return its claims. The token is encoded with the HS256 algorithm. If the decoding fails, return an empty JSON object string.

@param token The JWT token to decode.
@param key The key used in encoding.

@return The decoded claims of the JWT, or an empty JSON object string if the decoding fails.
*/
std::string decode_json_web_token(const std::string& token, const std::string& key) {
    try {
        // Create a verifier object.
        // The default clock and provider are used for time-based claims and cryptographic operations.
        jwt::verifier<jwt::default_clock, jwt::default_provider> verifier;

        // Configure the verifier to allow the HS256 algorithm with the provided key.
        verifier.allow_algorithm(jwt::algorithm::hs256(key));

        // Decode the token. This step parses the token's structure (header, payload, signature).
        // It does not verify the signature or claims yet.
        auto decoded_token = jwt::decode(token);

        // Verify the decoded token. This step checks the signature using the provided key
        // and also verifies standard claims like expiration (exp) if present.
        // If verification fails (e.g., invalid signature, expired token), an exception will be thrown.
        verifier.verify(decoded_token);

        // If both decoding and verification are successful, extract and return the payload as a JSON string.
        return decoded_token.get_payload_json();
    } catch (const jwt::error::signature_verification_exception& e) {
        // Catch specific exception for invalid signature.
        // Return an empty JSON object string as per the requirement.
        return "{}";
    } catch (const jwt::error::token_parse_exception& e) {
        // Catch specific exception for malformed or unparsable tokens.
        // Return an empty JSON object string.
        return "{}";
    } catch (const jwt::error::token_verification_exception& e) {
        // Catch specific exception for other token verification failures (e.g., expired token,
        // invalid issuer/audience if configured in the verifier).
        // Return an empty JSON object string.
        return "{}";
    } catch (const std::exception& e) {
        // Catch any other standard exceptions that might occur during the process.
        // Return an empty JSON object string.
        return "{}";
    }
}
